<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {get,write,type Row} from './api'
import {useAuth} from './stores'
const route=useRoute(),router=useRouter(),auth=useAuth()
const term=ref<Row>({}),offers=ref<Row[]>([]),schedule=ref<Row>({draftItems:[],enrolledItems:[],cancelledItems:[]}),choices=ref<Row[]>([]),report=ref<Row[]>([])
const lastRosterId=ref('')
const assignments=ref<Row>({version:0,items:[]}),selectedTeaching=ref<string[]>([]),historical=ref<Row[]>([]),roster=ref<Row[]>([]),rosterId=ref(''),gradeValues=ref<Record<string,string>>({})
const people=ref<Row[]>([]),peopleTotal=ref(0),personPage=ref(1),search=ref(''),jobs=ref<Row[]>([]),bills=ref<Row[]>([]),audits=ref<Row[]>([]),currentJob=ref<Row|null>(null)
const catalogPage=ref(1),catalogTotal=ref(0),courseCache=new Map<string,Row>()
const busy=ref(false),dirty=ref(false),personDialog=ref(false),personForm=ref<Row>({}),credentials=ref<Row|null>(null),oldPassword=ref(''),newPassword=ref('')
const role=computed(()=>auth.user?.role??'STUDENT'),page=computed(()=>String(route.params.page??'password')),semester=computed(()=>term.value.registrationSemesterId??'2')
const menus:Record<string,Row[]>={STUDENT:[{id:'catalog',title:'课程目录',hint:'发现课程'},{id:'schedule',title:'我的课表',hint:'安排学习'},{id:'report-card',title:'成绩查询',hint:'学业记录'}],PROFESSOR:[{id:'assignments',title:'授课安排',hint:'当前学期'},{id:'grades',title:'名单与成绩',hint:'学生学业'}],REGISTRAR:[{id:'students',title:'学生管理',hint:'人员档案'},{id:'professors',title:'教师管理',hint:'人员档案'},{id:'close',title:'注册关闭',hint:'确认与结算'},{id:'billing',title:'计费状态',hint:'发送与回执'},{id:'audit',title:'操作记录',hint:'变更追踪'}]}
const menu=computed(()=>menus[role.value]),title=computed(()=>page.value==='password'?'修改密码':menu.value.find(m=>m.id===page.value)?.title??'学业服务')
const primary=computed(()=>choices.value.filter(c=>c.choiceType==='PRIMARY')),alternate=computed(()=>choices.value.filter(c=>c.choiceType==='ALTERNATE'))
const filtered=computed(()=>offers.value.filter(o=>!search.value||o.name.includes(search.value)||String(o.id).includes(search.value)))
const canWrite=computed(()=>term.value.state==='OPEN')
const week=['','周一','周二','周三','周四','周五','周六','周日']
const status:Record<string,string>={OPEN:'注册开放',CLOSED:'注册已关闭',CLOSING:'处理中',CONFIRMED:'已成立',CANCELLED:'已停开',DRAFT:'草稿',SUBMITTED:'已正式提交',FINALIZED:'已确认',DELETED:'已删除',REQUESTED:'已受理',RUNNING:'处理中',BLOCKED_BUSY:'业务忙，等待重试',FAILED_LOCAL:'本地关闭失败',LOCAL_COMMITTED:'注册已关闭，计费待确认',COMPLETE:'全部完成',PENDING:'待发送',RETRYING:'等待重试',SENDING:'发送中',SENT:'已确认',ENROLLED:'在读',GRADUATED:'已毕业',SUSPENDED:'休学',ON_DUTY:'在岗',ON_LEAVE:'离岗',RETIRED:'退休'}
function state(s:string){return status[s]??s}
function times(o:Row){return (o.meetings??[]).map((m:Row)=>`${week[m.weekday]} ${m.startTime.slice(0,5)}–${m.endTime.slice(0,5)}`).join(' / ')}
function notice(e:any){ElMessage.error(`${e.message}${e.traceId?' · '+e.traceId.slice(0,8):''}`)}
async function action(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e){notice(e)}finally{busy.value=false}}
async function loadOffers(){const data=await get(`/catalog/offerings?size=20&page=${catalogPage.value}&q=${encodeURIComponent(search.value)}`);offers.value=data.items;catalogTotal.value=data.total;for(const o of offers.value)courseCache.set(o.id,o)}
async function loadSchedule(){try{
  const result=await get(`/student/schedules/${semester.value}`)
  if(page.value==='schedule')result.enrolledItems=await Promise.all(result.enrolledItems.map(async(e:Row)=>{
    try{const detail=await get(`/catalog/offerings/${encodeURIComponent(e.offeringId)}`);return {...e,professorName:detail.professorName,meetings:detail.meetings}}
    catch{return {...e,detailUnavailable:true}}
  }))
  return result
}catch(e:any){if(page.value==='schedule'&&e.status===404&&e.code==='SCHEDULE_NOT_FOUND')return {state:'DRAFT',version:0,draftItems:[],enrolledItems:[],cancelledItems:[]};throw e}}
async function load(){busy.value=true;try{
  if(auth.user?.mustChangePassword||page.value==='password')return
  term.value=await get('/semesters/registration-current')
  if(role.value==='STUDENT'){
    if(page.value!=='schedule')await loadOffers()
    schedule.value=await loadSchedule()
    choices.value=schedule.value.draftItems.map((i:Row)=>({offeringId:i.offeringId,choiceType:i.choiceType,order:i.choiceOrder}));dirty.value=false
    if(page.value==='report-card')report.value=await get('/student/report-card')
  }else if(role.value==='PROFESSOR'){
    offers.value=await get('/professor/eligible-offerings');assignments.value=await get(`/professor/teaching-assignments/${semester.value}`);selectedTeaching.value=assignments.value.items.map((i:Row)=>i.id)
    historical.value=await get('/professor/historical-offerings')
    if(page.value==='grades'&&!rosterId.value&&historical.value.length){rosterId.value=historical.value[0].id;await loadRoster()}
  }else if(['students','professors'].includes(page.value)){await loadPeople()}
  else if(page.value==='close'){offers.value=(await get('/registrar/overview')).offerings;jobs.value=await get('/registrar/close-jobs');if(jobs.value.length)currentJob.value=await get(`/registrar/close-jobs/${jobs.value[0].id}`)}
  else if(page.value==='billing')bills.value=await get('/registrar/billing-records')
  else if(page.value==='audit')audits.value=(await get('/registrar/audit-events?size=100')).items
}catch(e){notice(e)}finally{busy.value=false}}
async function loadPeople(){const data=await get(`/registrar/${page.value}?q=${encodeURIComponent(search.value)}&page=${personPage.value}&size=10`);people.value=data.items;peopleTotal.value=data.total}
function choose(o:Row,type:string){if(choices.value.some(c=>c.offeringId===o.id)){ElMessage.warning('这个班已经在方案中');return}const max=type==='PRIMARY'?4:2,n=choices.value.filter(c=>c.choiceType===type).length;if(n>=max){ElMessage.warning(type==='PRIMARY'?'最多4门主选':'最多2门备选');return}choices.value.push({offeringId:o.id,choiceType:type,order:n+1});dirty.value=true}
function remove(id:string){const item=choices.value.find(c=>c.offeringId===id);if(!item)return;choices.value=choices.value.filter(c=>c.offeringId!==id);choices.value.filter(c=>c.choiceType===item.choiceType).forEach((c,i)=>c.order=i+1);dirty.value=true}
function course(id:string){return courseCache.get(id)?.name??schedule.value.draftItems.find((i:Row)=>i.offeringId===id)?.name??id}
function full(id:string){return courseCache.get(id)?.enrolledCount>=10&&!schedule.value.enrolledItems.some((e:Row)=>e.offeringId===id)}
async function save(submit:boolean){if(submit&&primary.value.some(c=>full(c.offeringId))){ElMessage.warning('所选班已满员，请先调整方案');return}await action(async()=>{await write(submit?'POST':'PUT',`/student/schedules/${semester.value}/${submit?'submit':'draft'}`,{expectedVersion:schedule.value.version,choiceItems:choices.value});dirty.value=false;await load();ElMessage.success(submit?'正式课表已更新':'草稿已保存，正式课表不变')})}
async function deleteSchedule(){try{await ElMessageBox.confirm('删除后将释放当前正式名额。重新建立需要4主选2备选。','删除我的课表',{type:'warning'});await action(async()=>{await write('DELETE',`/student/schedules/${semester.value}`,{expectedVersion:schedule.value.version});dirty.value=false;await load();ElMessage.success('课表已删除')})}catch{}}
async function teach(){await action(async()=>{await write('PUT',`/professor/teaching-assignments/${semester.value}`,{expectedVersion:assignments.value.version,offeringIds:selectedTeaching.value});dirty.value=false;await load();ElMessage.success('授课安排已更新')})}
async function loadRoster(){if(!rosterId.value)return;roster.value=await get(`/professor/offerings/${rosterId.value}/roster`);gradeValues.value=Object.fromEntries(roster.value.map(r=>[r.enrollmentId,r.grade??'']));if(page.value==='grades')dirty.value=false;lastRosterId.value=rosterId.value}
async function switchRoster(){if(dirty.value){try{await ElMessageBox.confirm('成绩修改尚未保存，确认切换班级？','未保存修改')}catch{rosterId.value=lastRosterId.value;return}}await loadRoster()}
async function saveGrades(){await action(async()=>{const updates=roster.value.filter(r=>(gradeValues.value[r.enrollmentId]||null)!==(r.grade??null)).map(r=>({enrollmentId:r.enrollmentId,grade:gradeValues.value[r.enrollmentId]||null,expectedVersion:r.version}));await write('PUT',`/professor/offerings/${rosterId.value}/grades`,{updates});await loadRoster();ElMessage.success('成绩已保存；留空不会清除已有成绩')})}
async function editPerson(row?:Row){personForm.value=row?await get(`/registrar/${page.value}/${row.id}`):{name:'',birthDate:'2004-01-01',ssn:'',status:page.value==='students'?'ENROLLED':'ON_DUTY',graduationDate:null,department:''};personDialog.value=true}
async function savePerson(){await action(async()=>{const f=personForm.value,body:Row={name:f.name,birthDate:f.birthDate,ssn:f.ssn,status:f.status};body[page.value==='students'?'graduationDate':'department']=page.value==='students'?(f.graduationDate||null):f.department;if(f.id)body.expectedVersion=f.version;const result=await write(f.id?'PUT':'POST',`/registrar/${page.value}${f.id?'/'+f.id:''}`,body);personDialog.value=false;if(result.credentialDelivery)credentials.value=result;await loadPeople();ElMessage.success(f.id?'人员资料已更新':'人员和账号已创建')})}
async function deletePerson(row:Row){try{await ElMessageBox.confirm(`确认删除“${row.name}”？历史记录保留；存在当前关联时会拒绝。`,'删除人员',{type:'warning'});await action(async()=>{await write('DELETE',`/registrar/${page.value}/${row.id}?expectedVersion=${row.version}`);await loadPeople();ElMessage.success('人员已逻辑删除')})}catch{}}
async function resetPassword(row:Row){try{await ElMessageBox.confirm(`确认重置“${row.name}”的登录密码？旧登录将失效，新密码仅显示一次。`,'重置密码',{type:'warning'});await action(async()=>{const person=await get(`/registrar/${page.value}/${row.id}`);credentials.value=await write('POST',`/registrar/accounts/${person.accountId}/reset-password`);ElMessage.success('旧会话已失效')})}catch{}}
async function close(){try{await ElMessageBox.confirm('关闭后不能继续选课或修改授课。系统将处理备选、停开班级并生成最终账单。','关闭注册',{type:'warning',confirmButtonText:'确认关闭'});await action(async()=>{currentJob.value=await write('POST',`/registrar/semesters/${semester.value}/close-jobs`);ElMessage.success('请求已受理，正在处理');await load()})}catch{}}
async function retryBill(b:Row){await action(async()=>{await write('POST',`/registrar/billing-records/${b.id}/retry`);await load()})}
async function password(){await action(async()=>{await write('POST','/auth/password',{oldPassword:oldPassword.value,newPassword:newPassword.value});oldPassword.value='';newPassword.value='';auth.reset();await router.push('/login');ElMessage.success('密码已修改，请重新登录')})}
async function logout(){await auth.logout();dirty.value=false;await router.push('/login')}
onBeforeRouteLeave(async()=>{if(dirty.value){try{await ElMessageBox.confirm('当前修改还没有保存，确认离开？','未保存修改');dirty.value=false}catch{return false}}})
watch(()=>route.fullPath,()=>{search.value='';personPage.value=1;rosterId.value='';load()})
let poll:ReturnType<typeof setInterval>,searchTimer:ReturnType<typeof setTimeout>
watch(search,()=>{if(role.value==='STUDENT'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{catalogPage.value=1;loadOffers().catch(notice)},300)}})
onMounted(()=>{load();poll=setInterval(async()=>{if(busy.value)return;try{if(role.value==='STUDENT'&&['catalog','schedule'].includes(page.value)){const previous=term.value.state;term.value=await get('/semesters/registration-current');if(previous!==term.value.state)await load();else if(page.value==='catalog')await loadOffers();else schedule.value=await loadSchedule();}if(role.value==='REGISTRAR'&&['close','billing'].includes(page.value))await load()}catch{}},5000)})
onUnmounted(()=>{clearInterval(poll);clearTimeout(searchTimer)})
</script>
<template>
  <div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-symbol">W</span><span>WYLIE<small>COLLEGE</small></span></div><div class="sidebar-caption">{{role==='STUDENT'?'学生工作台':role==='PROFESSOR'?'教师工作台':'教务管理台'}}</div><nav><router-link v-for="m in menu" :key="m.id" :to="`/${role.toLowerCase()}/${m.id}`" :class="{active:page===m.id}"><span>{{m.title}}</span><small>{{m.hint}}</small></router-link></nav><div class="sidebar-bottom"><div class="semester-note">学期事务<br><b>{{term.name??'学业服务平台'}}</b></div><button @click="router.push('/account/password')">修改密码</button><button @click="logout">退出登录 ↗</button></div></aside>
  <main class="workspace"><header class="topbar"><div><span class="breadcrumb">学业服务 / {{title}}</span><h1>{{title}}</h1></div><div class="user-chip"><span class="avatar">{{auth.user?.username.slice(0,1).toUpperCase()}}</span><span>{{auth.user?.username}}<small>{{role==='STUDENT'?'学生':role==='PROFESSOR'?'教师':'教务管理员'}}</small></span></div></header>
    <div v-if="term.fixedClock&&page!=='password'" class="clock-notice">演示日期：{{new Date(term.clock).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}<span class="status-pill">{{state(term.state)}}</span></div>
    <section v-if="page==='password'" class="panel password-panel"><span class="eyebrow">ACCOUNT SECURITY</span><h2>设置你的个人密码</h2><p class="muted">密码修改后，旧登录状态将失效。新密码至少12个字符。</p><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="oldPassword" type="password" show-password /></el-form-item><el-form-item label="新密码"><el-input v-model="newPassword" type="password" show-password /></el-form-item><el-button type="primary" :loading="busy" @click="password">保存并重新登录</el-button></el-form></section>
    <template v-else-if="role==='STUDENT'&&page==='catalog'">
      <section class="intro-card"><div><span class="eyebrow">PLAN YOUR SEMESTER</span><h2>让每一门选择，都有方向。</h2><p>先保存方案，再正式提交。备选课程将在注册关闭时按规则尝试补位。</p></div><div class="intro-number">{{schedule.enrolledItems.length}}<small>门正式课程</small></div></section>
      <div class="student-grid"><section><div class="section-heading"><h2>{{page==='catalog'?'本学期开课':'调整我的方案'}} <small>{{catalogTotal}} 个班</small></h2><el-input v-model="search" placeholder="搜索课程名称或班号" clearable class="search-input" /></div><div v-loading="busy" class="course-grid"><article v-for="o in filtered" :key="o.id" class="course-card"><div class="course-meta"><span>{{o.department}}</span><span :class="['capacity',o.enrolledCount>=10?'full':'']">{{o.enrolledCount}} / {{o.capacity}}</span></div><h3>{{o.name}}</h3><div class="course-code">班号 {{o.id}} · {{o.professorName??'待安排教师'}}</div><p class="course-time">{{times(o)}}</p><p class="prerequisite">先修：{{o.prerequisites?.map((p:Row)=>p.name).join('、')||'无'}}</p><div class="course-actions"><el-button :disabled="!canWrite||o.state!=='OPEN'||choices.some(c=>c.offeringId===o.id)" @click="choose(o,'PRIMARY')">加入主选</el-button><el-button link :disabled="!canWrite||o.state!=='OPEN'||choices.some(c=>c.offeringId===o.id)" @click="choose(o,'ALTERNATE')">加入备选 +</el-button><span v-if="o.state!=='OPEN'" class="muted">{{state(o.state)}}</span></div></article><el-empty v-if="!filtered.length" description="没有匹配的开课班" /></div><el-pagination v-model:current-page="catalogPage" :total="catalogTotal" :page-size="20" layout="prev,pager,next,total" @current-change="loadOffers" /></section>
        <aside class="selection-panel"><div class="selection-title"><h2>我的选课方案</h2><span>{{dirty?'未保存':state(schedule.state)}}</span></div><p class="muted">首次提交需要4主选 + 2备选。</p><h4>主选 <span>{{primary.length}} / 4</span></h4><div v-for="c in primary" :key="c.offeringId" class="choice-row"><span class="order-dot">{{c.order}}</span><div>{{course(c.offeringId)}}<small :class="{danger:full(c.offeringId)}">{{full(c.offeringId)?'已满员，请调整':'班号 '+c.offeringId}}</small></div><button v-if="canWrite" @click="remove(c.offeringId)" aria-label="移除课程">×</button></div><p v-if="!primary.length" class="empty-choice">从目录中添加主选课程</p><h4>备选 <span>{{alternate.length}} / 2</span></h4><div v-for="c in alternate" :key="c.offeringId" class="choice-row alternate"><span class="order-dot">{{c.order}}</span><div>{{course(c.offeringId)}}<small>班号 {{c.offeringId}}</small></div><button v-if="canWrite" @click="remove(c.offeringId)" aria-label="移除备选">×</button></div><p v-if="!alternate.length" class="empty-choice">备选不占用正式名额</p><div class="selection-buttons"><el-button :disabled="!canWrite" :loading="busy" @click="save(false)">保存草稿</el-button><el-button type="primary" :disabled="!canWrite" :loading="busy" @click="save(true)">正式提交</el-button></div><button class="delete-link" :disabled="!canWrite" @click="deleteSchedule">删除课表并释放名额</button><div class="formal-list"><h4>当前正式课表 <span>{{schedule.enrolledItems.length}} 门</span></h4><div v-for="e in schedule.enrolledItems" :key="e.offeringId">{{e.name}}<small>{{e.originType==='ALTERNATE'?'备选补位':'主选'}} · 班 {{e.offeringId}}</small></div><p v-if="!schedule.enrolledItems.length" class="muted">尚无正式注册课程</p><div v-for="e in schedule.cancelledItems" :key="e.offeringId" class="cancelled">{{e.name}}<small>已取消 · {{e.cancelReason==='LOW_ENROLLMENT'?'人数不足':e.cancelReason==='NO_INSTRUCTOR'?'没有教师':e.cancelReason==='REPLACED_BY_ALTERNATE'?'备选替换':'状态不符合'}}</small></div></div></aside></div>
    </template>
    <section v-else-if="role==='STUDENT'&&page==='schedule'" class="panel schedule-view" v-loading="busy">
      <div class="section-heading"><div><h2>我的课表</h2><p class="muted">正式课程以注册结果为准；已保存的主选和备选方案单独展示，草稿和待补位备选不占用正式名额。</p></div><el-button @click="router.push('/student/catalog')">前往课程目录调整选课</el-button></div>
      <el-empty v-if="!busy&&!schedule.enrolledItems.length&&!schedule.draftItems.length&&!schedule.cancelledItems.length" description="暂无已选课程，请前往课程目录选课" />
      <template v-else-if="!busy">
        <h3>正式课程（{{schedule.enrolledItems.length}} 门）</h3>
        <el-table v-if="schedule.enrolledItems.length" :data="schedule.enrolledItems" class="enrolled-table" stripe><el-table-column prop="name" label="课程" /><el-table-column prop="offeringId" label="班号" /><el-table-column label="授课教师"><template #default="{row}">{{row.detailUnavailable?'详情暂不可用':row.professorName||'待安排教师'}}</template></el-table-column><el-table-column label="上课时间" min-width="180"><template #default="{row}">{{row.detailUnavailable?'详情暂不可用':times(row)||'未提供'}}</template></el-table-column><el-table-column label="上课地点"><template #default>未提供</template></el-table-column><el-table-column label="选课来源"><template #default="{row}">{{row.originType==='ALTERNATE'?'备选补位':'主选'}}</template></el-table-column><el-table-column label="状态"><template #default>已正式注册</template></el-table-column></el-table>
        <p v-else class="muted">暂无正式注册课程；保存草稿后仍需正式提交。</p>
        <template v-if="schedule.draftItems.length"><h3>已保存选课方案</h3><p class="muted">课表状态：{{state(schedule.state)}}。方案与上方正式课表分别展示；主选以正式注册结果为准，备选仅在补位成功后成为正式课程。</p><el-table :data="schedule.draftItems" class="draft-table" stripe><el-table-column prop="name" label="课程" /><el-table-column prop="offeringId" label="班号" /><el-table-column label="志愿"><template #default="{row}">{{row.choiceType==='PRIMARY'?'主选':'备选'}} {{row.choiceOrder}}</template></el-table-column><el-table-column label="记录状态"><template #default="{row}">{{state(row.state)}}</template></el-table-column></el-table></template>
        <template v-if="schedule.cancelledItems.length"><h3>已取消记录（不计入正式课程）</h3><el-table :data="schedule.cancelledItems" class="cancelled-table" stripe><el-table-column prop="name" label="课程" /><el-table-column prop="offeringId" label="班号" /><el-table-column label="取消原因"><template #default="{row}">{{row.cancelReason==='LOW_ENROLLMENT'?'人数不足':row.cancelReason==='NO_INSTRUCTOR'?'没有教师':row.cancelReason==='REPLACED_BY_ALTERNATE'?'备选替换':row.cancelReason}}</template></el-table-column></el-table></template>
      </template>
    </section>
    <section v-else-if="role==='STUDENT'" class="panel"><div class="section-heading"><div><h2>上一已完成学期成绩</h2><p class="muted">F 为不通过，I 为未完成；“未录入”表示尚未填写成绩。</p></div><span class="pill">学业记录</span></div><el-table :data="report" stripe><el-table-column prop="name" label="课程" /><el-table-column prop="offeringId" label="班号" /><el-table-column prop="professorName" label="授课教师" /><el-table-column label="成绩"><template #default="{row}"><span :class="['grade-badge',row.grade==='F'?'danger':'']">{{row.grade??'未录入'}}</span></template></el-table-column></el-table><el-empty v-if="!report.length" description="暂无上一学期成绩" /></section>
    <template v-else-if="role==='PROFESSOR'"><section v-if="page==='assignments'" class="panel"><div class="section-heading"><div><h2>当前学期授课安排</h2><p class="muted">仅可选择具有授课资格的班。修改将整体提交，时间冲突或占用时保留原安排。</p></div><el-button type="primary" :disabled="!canWrite" :loading="busy" @click="teach">保存授课安排</el-button></div><el-checkbox-group v-model="selectedTeaching" @change="dirty=true"><div class="teacher-grid"><article v-for="o in offers" :key="o.id" class="course-card"><el-checkbox :value="o.id" :disabled="!canWrite||(o.professorId&&o.professorId!==auth.user?.professorId)">{{o.name}} · {{o.id}}</el-checkbox><p>{{times(o)}}</p><small class="muted">{{o.professorName??'暂无教师'}} · {{o.enrolledCount}}人</small><el-button v-if="o.professorId===auth.user?.professorId" link @click="rosterId=o.id;loadRoster()">查看正式名单</el-button></article></div></el-checkbox-group><el-table v-if="roster.length" :data="roster"><el-table-column prop="studentId" label="学生ID" /><el-table-column prop="name" label="正式名单" /></el-table></section>
      <section v-else class="panel"><div class="section-heading"><div><h2>上一已完成学期 · 名单与成绩</h2><p class="muted">整批保存，留空不清除已有成绩。</p></div><el-button type="primary" :loading="busy" @click="saveGrades">保存成绩</el-button></div><el-select v-model="rosterId" placeholder="选择本人历史授课班" style="width:360px" @change="switchRoster"><el-option v-for="o in historical" :key="o.id" :label="`${o.name} · ${o.id}`" :value="o.id" /></el-select><el-table :data="roster" class="spaced-table"><el-table-column prop="studentId" label="学生ID" /><el-table-column prop="name" label="姓名" /><el-table-column label="已有成绩"><template #default="{row}">{{row.grade??'未录入'}}</template></el-table-column><el-table-column label="录入成绩"><template #default="{row}"><el-select v-model="gradeValues[row.enrollmentId]" @change="dirty=true"><el-option label="留空 / 保持已有成绩" value="" /><el-option v-for="g in ['A','B','C','D','F','I']" :key="g" :label="g" :value="g" /></el-select></template></el-table-column></el-table><el-empty v-if="!historical.length" description="暂无本人上一学期授课班" /></section></template>
    <template v-else><section v-if="['students','professors'].includes(page)" class="panel"><div class="section-heading"><div><h2>{{page==='students'?'学生':'教师'}}档案</h2><p class="muted">删除保留历史记录；当前业务关联须先解除。</p></div><div><el-button type="primary" @click="editPerson()">新增{{page==='students'?'学生':'教师'}}</el-button></div></div><el-input v-model="search" placeholder="按姓名或ID搜索" clearable class="person-search" @keyup.enter="personPage=1;loadPeople()" /><el-button @click="personPage=1;loadPeople()">搜索</el-button><el-table :data="people" stripe v-loading="busy" class="spaced-table"><el-table-column prop="id" label="ID" width="90" /><el-table-column prop="name" label="姓名" /><el-table-column prop="birthDate" label="生日" /><el-table-column prop="ssn" label="SSN（脱敏）" /><el-table-column label="状态"><template #default="{row}"><span class="status-pill">{{state(row.status)}}</span></template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link type="primary" @click="editPerson(row)">编辑</el-button><el-button link :disabled="busy" @click="resetPassword(row)">重置密码</el-button><el-button link type="danger" @click="deletePerson(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="personPage" :total="peopleTotal" :page-size="10" layout="prev,pager,next,total" @current-change="loadPeople" /></section>
      <section v-else-if="page==='close'" class="panel"><div class="section-heading"><div><h2>确认本学期注册结果</h2><p class="muted">关闭会处理备选、取消不成立班级，并发送最终学费事务。</p></div><el-button type="primary" :loading="busy" :disabled="term.state==='CLOSED'" @click="close">{{currentJob&&['BLOCKED_BUSY','FAILED_LOCAL'].includes(currentJob.state)?'重试关闭':'关闭注册'}}</el-button></div><div v-if="currentJob" class="job-summary"><span class="eyebrow">关闭任务 #{{currentJob.id}}</span><h3>{{state(currentJob.state)}}</h3><p v-if="currentJob.summary">参与学生 {{currentJob.summary.studentCount}} · 成立班 {{currentJob.summary.confirmedClasses}} · 停开班 {{currentJob.summary.cancelledClasses}}</p><p v-if="currentJob.lastError" class="danger">{{currentJob.lastError}}</p><small>“计费待确认”表示本地课表已经确定，仍需等待外部回执。</small></div><el-table :data="offers"><el-table-column prop="name" label="课程" /><el-table-column prop="id" label="班号" /><el-table-column prop="professorName" label="教师" /><el-table-column prop="enrolledCount" label="正式人数" /><el-table-column label="班状态"><template #default="{row}">{{state(row.state)}}</template></el-table-column></el-table></section>
      <section v-else-if="page==='billing'" class="panel"><div class="section-heading"><div><h2>最终账单与发送状态</h2><p class="muted">发送失败将持续重试；相同业务不会重复收费。</p></div><el-button @click="load">刷新</el-button></div><el-table :data="bills" stripe><el-table-column prop="id" label="账单" width="70" /><el-table-column prop="studentId" label="学生" width="80" /><el-table-column label="学费"><template #default="{row}">¥{{row.amount}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.state==='SENT'?'success':'warning'">{{state(row.state)}}</el-tag></template></el-table-column><el-table-column prop="attemptCount" label="发送尝试" /><el-table-column prop="externalRef" label="外部回执" min-width="190" /><el-table-column prop="lastError" label="最近错误" /><el-table-column label="操作"><template #default="{row}"><el-button link :disabled="['SENT','SENDING'].includes(row.state)" @click="retryBill(row)">立即重试</el-button></template></el-table-column></el-table><el-empty v-if="!bills.length" description="注册关闭后将生成最终账单" /></section>
      <section v-else class="panel"><h2>操作记录</h2><el-table :data="audits" stripe><el-table-column prop="id" label="编号" width="75" /><el-table-column prop="eventType" label="事件" /><el-table-column prop="entityId" label="对象" /><el-table-column prop="createdAt" label="时间" /><el-table-column prop="detail" label="摘要" /><el-table-column prop="traceId" label="关联标识" /></el-table></section></template>
    <footer class="workspace-footer">Wylie College · 学业服务平台<span>{{term.name}}</span></footer>
  </main>
  <el-dialog v-model="personDialog" :title="personForm.id?'编辑人员资料':'新增人员与账号'" width="520px"><el-form label-position="top"><el-form-item label="姓名"><el-input v-model="personForm.name" maxlength="100" /></el-form-item><el-form-item label="生日"><el-date-picker v-model="personForm.birthDate" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="SSN（仅使用虚构信息）"><el-input v-model="personForm.ssn" placeholder="9位数字，可使用XXX-XX-XXXX" /></el-form-item><el-form-item label="状态"><el-select v-model="personForm.status"><el-option v-for="s in page==='students'?['ENROLLED','GRADUATED','SUSPENDED']:['ON_DUTY','ON_LEAVE','RETIRED']" :key="s" :label="state(s)" :value="s" /></el-select></el-form-item><el-form-item v-if="page==='students'" label="计划毕业日期（可空）"><el-date-picker v-model="personForm.graduationDate" value-format="YYYY-MM-DD" clearable /></el-form-item><el-form-item v-else label="院系"><el-input v-model="personForm.department" /></el-form-item></el-form><template #footer><el-button @click="personDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="savePerson">保存</el-button></template></el-dialog>
  <el-dialog :model-value="!!credentials" title="一次性账号凭据" width="500px" @close="credentials=null"><p>账号：<b>{{credentials?.username}}</b></p><p>账号 ID：{{credentials?.accountId??credentials?.id}}</p><p class="credential-value">{{credentials?.credentialDelivery?.temporaryPassword}}</p><p class="muted">请妥善交付。关闭后无法再次查看；首次登录必须改密。</p><template #footer><el-button type="primary" @click="credentials=null">我已保存</el-button></template></el-dialog>
  </div>
</template>
